def transform(grid):
    mid = next(i for i, row in enumerate(grid) if row and all(v == 5 for v in row))
    upper, lower = grid[:mid], grid[mid+1:]
    counts = {c: (sum(row.count(c) for row in upper), sum(row.count(c) for row in lower)) for c in (2, 4)}
    color = max((2, 4), key=lambda c: counts[c][1] - counts[c][0])
    return [[color, color], [color, color]]
